  /** ⏳️ Settles every turn one bounded request/response leg needs, then four quiet ones. */
  async function settleInferenceTurns(): Promise<void> {
    for (let turn = 0; turn < 40; turn += 1) await new Promise((resolve) => setTimeout(resolve, 0));
  }
  //#endregion 💡️InferencePortTests

  //#region 🔖️OfflineResilienceTests
  // 🧬️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME (web-backbone) findings 1/2/3/5: stream-primary folder
  // watch (`backbone.folder` on the page's stream channel) with a suppressed sanity-poll fallback, abort-on-close,
  // and the bounded lossless mutation outbox. No real sleeps — `vi.useFakeTimers()` drives every
  // timer-dependent assertion, and every fetch/socket/stream is a controllable local fake.
  describe("backbone-worker offline resilience", () => {
    type StreamMuxEndpointV1 = import("../../../../🧰️framework/🔨️modules/🚪️io/🔀️stream-mux/🟦️.ts").StreamMuxEndpointV1;
    type StreamMuxHandlersV1 = import("../../../../🧰️framework/🔨️modules/🚪️io/🔀️stream-mux/🟦️.ts").StreamMuxHandlersV1;
    /** 🔀️ The page's stream channel as the worker sees it: every open is a recorded stream whose handlers the test drives. */
    class FakeStreamEndpoint implements StreamMuxEndpointV1 {
      readonly streams: { readonly route: string; readonly key: string; readonly handlers: StreamMuxHandlersV1; closed: boolean }[] = [];
      open(route: string, key: string, handlers: StreamMuxHandlersV1, options: { readonly signal?: AbortSignal } = {}): { close(): void } {
        const stream = { route, key, handlers, closed: false };
        this.streams.push(stream);
        options.signal?.addEventListener("abort", () => (stream.closed = true), { once: true });
        return { close: () => (stream.closed = true) };
      }
    }

    /** 🕸️ `implements WebSocket` on purpose: the worker types `state.socket` and every `handleHubFrame`
     * argument as the DOM `WebSocket`, so a fake that merely resembles one has to be forced in at each
     * call site. Declaring the interface makes the compiler name a member the worker could reach and
     * this fake has not implemented, which is the whole point of the double. The members below the
     * `sent` ledger are the ones the worker never calls; they exist so the type is honest. */
    class FakeHubWebSocket implements WebSocket {
      static readonly CONNECTING = 0;
      static readonly OPEN = 1;
      static readonly CLOSING = 2;
      static readonly CLOSED = 3;
      static instances: FakeHubWebSocket[] = [];
      readonly CONNECTING = 0 as const;
      readonly OPEN = 1 as const;
      readonly CLOSING = 2 as const;
      readonly CLOSED = 3 as const;
      readonly url: string;
      readonly protocol = "semio.session.v1";
      readonly protocols: string | string[] | undefined;
      readonly extensions = "";
      readonly bufferedAmount = 0;
      readyState = FakeHubWebSocket.CONNECTING;
      binaryType: BinaryType = "blob";
      readonly sent: Uint8Array[] = [];
      onopen: (() => void) | null = null;
      onmessage: ((event: { data: ArrayBuffer }) => void) | null = null;
      onclose: (() => void) | null = null;
      onerror: (() => void) | null = null;
      constructor(url: string, protocols?: string | string[]) {
        this.url = url;
        this.protocols = protocols;
        FakeHubWebSocket.instances.push(this);
      }
      send(data: Uint8Array): void {
        this.sent.push(data);
      }
      addEventListener(): void {
        throw new Error("fake hub socket: the worker dials through the on* handlers, never addEventListener");
      }
      removeEventListener(): void {
        throw new Error("fake hub socket: the worker dials through the on* handlers, never removeEventListener");
      }
      dispatchEvent(): boolean {
        throw new Error("fake hub socket: the worker never dispatches synthetic events");
      }
      open(): void {
        this.readyState = FakeHubWebSocket.OPEN;
        this.onopen?.();
      }
      close(_code?: number, _reason?: string): void {
        this.readyState = FakeHubWebSocket.CLOSED;
        this.onclose?.();
      }
    }

    function folderOnlyConfig(documentId: string): ArtifactActorConfig {
      return { documentId, schema: "demo/v1", bindings: [{ kind: "folder", dataClass: "persistedLocalOnly", path: `/tmp/${documentId}` }], actor: "actor-1" };
    }

    function exactDocumentBackboneMessage(
      envelope: MutationEnvelope,
      diffPayload = encodePackValue(envelope.diff.payload),
      timestamp: Readonly<{ actor: bigint; physical_ms: bigint; logical: bigint }> = { actor: 1n, physical_ms: 9_007_199_254_740_992n, logical: 3n },
    ): Uint8Array {
      return encodeBackboneMessage({
        kind: "mutations",
        envelopes: encodeDocumentBackboneEnvelopeBatchExact([{
          mutation_id: envelope.id,
          document_id: envelope.document,
          actor: envelope.actor,
          dependencies: envelope.deps ?? [],
          observed: null,
          target: [],
          diff: { schema: envelope.diff.schemaId, payload: diffPayload },
          inverse: { schema: envelope.inverse.inverseDiff.schemaId, payload: encodePackValue(envelope.inverse.inverseDiff.payload) },
          timestamp,
          transaction: null,
        }]),
      });
    }

    /** 🚚️ The backing buffer of a view the worker transfers, refusing a shared one.
     * `Uint8Array.buffer` is an `ArrayBufferLike`, and a `SharedArrayBuffer` is not `Transferable`;
     * `instanceof` is what turns that into a checked narrowing rather than an assertion. */
    function transferableBuffer(bytes: Uint8Array): ArrayBuffer {
      const buffer = bytes.buffer;
      if (!(buffer instanceof ArrayBuffer)) throw new Error("worker transfer requires a non-shared buffer");
      return buffer;
    }

    /** 🧊️ Puts one hub-bound document into the state production reaches after a verified cold
     * transfer: the execution-target lease it was admitted under, the published pack/spr pair, the
     * baseline frontier, and the real `VerifiedColdDocumentPair` minted over all three. The owner is
     * a nominal class guarded by a private mint token, so no structural stand-in can carry its
     * retention or page cursor; every law below measures `documentBackboneAdmissionReady`, which
     * calls `assertCurrent()` on exactly this object. */
    function installVerifiedDocumentBackbonePair(state: ArtifactState, baseline?: Partial<WireFrontierSummary>): WireFrontierSummary {
