type TrustedBootstrapMaterializationV1 = Readonly<{ profileId: string; generationId: string; bundleSha256: string; bundlePath: string }>;
type TrustedBootstrapCurrentPointerV1 = Readonly<{ profileId: string; generationId: string; bundleSha256: string; publicationRevision: string }>;
type TrustedBootstrapPublishedV1 = TrustedBootstrapMaterializationV1 & Readonly<{ publicationRevision: string; currentSha256: string }>;

function trustedBootstrapWriteNew(path: string, bytes: Uint8Array, check: () => void): void {
  check();
  const output = openSync(path, "wx", 0o600);
  let complete = false;
  try {
    let written = 0;
    while (written < bytes.byteLength) {
      check();
      const count = writeSync(output, bytes, written, Math.min(64 * 1024, bytes.byteLength - written));
      if (count <= 0) throw new Error("trusted staging write made no progress");
      written += count;
    }
    check();
    fsyncSync(output);
    check();
    complete = true;
  } finally {
    try {
      closeSync(output);
    } catch (error) {
      complete = false;
      throw error;
    } finally {
      if (!complete) rmSync(path, { force: true });
    }
  }
}

function trustedBootstrapFsyncDirectory(path: string): void {
  if (process.platform === "win32") return;
  const directory = openSync(path, "r");
  try {
    fsyncSync(directory);
  } finally {
    closeSync(directory);
  }
}

/** 🪪️ Projects only the schema-admitted fixed native codec closure into immutable generation inputs. */
function projectTrustedBootstrapCodecsV1(stdio: unknown, gis: unknown): Readonly<{ gisVersion: string; codecs: Readonly<Record<"gis" | "stdio", readonly TrustedBootstrapCodec[]>> }> {
  const fail = (): never => {
    throw new Error("trusted codec source is not the exact bounded native closure");
  };
  const record = (value: unknown, keys: readonly string[]): Record<string, any> => {
    if (!value || typeof value !== "object" || Array.isArray(value) || JSON.stringify(Object.keys(value).sort()) !== JSON.stringify([...keys].sort())) return fail();
    return value as Record<string, any>;
  };
  const identity = (value: unknown): value is string => typeof value === "string" && value.length > 0 && value.length <= 256 && !/[\u0000-\u001f\u007f]/u.test(value);
  const digest = (value: unknown): value is string => typeof value === "string" && /^(?!0{64}$)[0-9a-f]{64}$/u.test(value);
  const s = record(stdio, ["schema", "provider_id", "plugin_id", "package_id", "receipts"]);
  const g = record(gis, ["schema", "pluginId", "packageId", "packageVersion", "receipts", "hostile"]);
  if (s.schema !== "semio.stdio.native-openable-catalog-provider/v1" || s.provider_id !== "stdio/native-codecs/v1" || s.plugin_id !== "stdio" || s.package_id !== "semio:stdio" || !Array.isArray(s.receipts) || s.receipts.length !== 29) return fail();
  const hostile = ["missing", "duplicate", "foreign-package", "wrong-version", "bare-kind", "wrong-schema", "wrong-extension", "zero-hash"];
  if (
    g.schema !== "semio.gis.native-codec-receipts/v1" ||
    g.pluginId !== "gis" ||
    g.packageId !== "semio:gis" ||
    g.packageVersion !== "0.1.0" ||
    !Array.isArray(g.receipts) ||
    g.receipts.length !== 2 ||
    !Array.isArray(g.hostile) ||
    JSON.stringify([...g.hostile].sort()) !== JSON.stringify(hostile.sort())
  )
    return fail();
  const stdioRows = s.receipts.map((value: unknown) => {
    const fields = ["artifact", "factory_id", "descriptor_codec_id", "runtime_capability_id", "artifact_kind", "artifact_schema", "extension"];
    const row = record(value, [...fields, "pack_schema_hash", "protocol_source_sha256", "protocol_path", "definition_path"]);
    if (!fields.every((field) => identity(row[field])) || !digest(row.pack_schema_hash) || !digest(row.protocol_source_sha256) || typeof row.definition_path !== "string" || !/^✏️s\/🔌️plugins\/🗄️stdio\/🗿️artifacts\/[^/]+\/📜️artifact-definition\.json$/u.test(row.definition_path) || typeof row.protocol_path !== "string" || row.protocol_path.length > 1024 || !/^✏️s\/🔌️plugins\/🗄️stdio\/🗿️artifacts\/.+\/📡️\.protocol\.semio$/u.test(row.protocol_path))
      return fail();
    return Object.freeze({ artifactKind: row.artifact_kind as string, artifactSchema: row.artifact_schema as string, packSchemaHash: row.pack_schema_hash });
  });
  const gisRows = g.receipts.map((value: unknown) => {
    const row = record(value, ["factoryId", "kind", "schema", "extension", "capability", "packRecord", "protocolPath", "protocolBytes", "protocolSha256", "packSchemaHash"]);
    const family = row.kind === "s.gis.gismap" ? { id: "gismap", schema: "map", owner: "🗺️gismap" } : row.kind === "s.gis.gisterrain" ? { id: "gisterrain", schema: "terrain", owner: "🏔️gisterrain" } : fail();
    if (
      row.factoryId !== `gis.${family.id}.v1` ||
      row.schema !== `gis.${family.schema}` ||
      row.extension !== family.id ||
      row.capability !== `s.gis.${family.id}.codec.document` ||
      row.protocolPath !== `✏️s/🔌️plugins/🌍️gis/🗿️artifacts/${family.owner}/🏅️standards/🔖️1/🪆️subsets/✳️any/🧬️schema/📸️snapshot/💾️binary/📡️.protocol.semio` ||
      !Number.isSafeInteger(row.protocolBytes) ||
      row.protocolBytes < 1 ||
      row.protocolBytes > 65536 ||
      !digest(row.protocolSha256) ||
      !digest(row.packSchemaHash)
    )
      return fail();
    return Object.freeze({ artifactKind: row.kind as string, artifactSchema: row.schema as string, packSchemaHash: row.packSchemaHash as string });
  });
  for (const rows of [stdioRows, gisRows]) if (new Set(rows.map((row: TrustedBootstrapCodec) => JSON.stringify([row.artifactKind, row.artifactSchema]))).size !== rows.length) return fail();
  return Object.freeze({ gisVersion: g.packageVersion as string, codecs: Object.freeze({ stdio: Object.freeze(stdioRows.sort(trustedBootstrapCodecOrder)), gis: Object.freeze(gisRows.sort(trustedBootstrapCodecOrder)) }) });
}

/** 📸️ Captures both codec sources once before any long component build can outlive them. */
function captureTrustedBootstrapCodecsV1(repoRoot: string, check: (stage?: string) => void): ReturnType<typeof projectTrustedBootstrapCodecsV1> {
  const admission = { remaining: 128 * 1024 };
  let stdio: Uint8Array | undefined, gis: Uint8Array | undefined;
  try {
    stdio = readStableBuildFile(join(repoRoot, "🌎️hub/🧩️compositions/🗄️stdio/🔌️plugin/📇️catalog/📜️native-codec-factories.json"), 64 * 1024, admission, check);
    gis = readStableBuildFile(join(repoRoot, "🌎️hub/🧩️compositions/🌍️gis/📇️native-codecs/🔣️.json"), 64 * 1024, admission, check);
    check("project-codecs");
    const decoder = new TextDecoder("utf-8", { fatal: true });
    return projectTrustedBootstrapCodecsV1(JSON.parse(decoder.decode(stdio)), JSON.parse(decoder.decode(gis)));
  } catch (error) {
    throw new Error(`trusted codec capture: ${(error as Error).message}`);
  } finally {
    stdio?.fill(0);
    gis?.fill(0);
  }
}

/** 🧪️ Compares fixed source admission with package schemas and independent generation hashes. */
async function proveTrustedBootstrapCodecCaptureFixture(repoRoot: string): Promise<void> {
  const assert: (typeof import("node:assert"))["strict"] = (await import("node:assert/strict")).default;
  const { writeFileSync, truncateSync } = await import("node:fs");
  const root = join(repoRoot, "🌎️hub/🗿️artifact-authority/🔏️trusted-catalog/🧫️fixtures/🧊️codec-source");
  const fixture = JSON.parse(readFileSync(join(root, "🔣️.json"), "utf8"));
  assert.deepEqual(Object.keys(fixture), ["schema", "maximumSourceBytes", "maximumTotalBytes", "cases"]);
  assert.equal(fixture.schema, "semio.hub.codec-source.v1");
  assert.equal(fixture.maximumSourceBytes, 65_536);
  assert.equal(fixture.maximumTotalBytes, 131_072);
  assert.deepEqual(fixture.cases.map((row: any) => row.change), [
    "none", "permuted", "replaced-source", "invalid-hash", "zero-hash", "duplicate-stdio", "duplicate-gis", "unknown-root", "unknown-row",
    "foreign-package", "crossed-gis-schema", "zero-pack-schema-hash", "foreign-version", "invalid-utf8", "oversize", "cancelled",
  ]);
  for (const row of fixture.cases) assert.deepEqual(Object.keys(row), ["change", "accepted", "schemaAccepted"]);
  assert.equal(new Set(fixture.cases.map((row: any) => row.change)).size, fixture.cases.length);
  const sourcePaths = {
    stdio: "🌎️hub/🧩️compositions/🗄️stdio/🔌️plugin/📇️catalog/📜️native-codec-factories.json",
    gis: "🌎️hub/🧩️compositions/🌍️gis/📇️native-codecs/🔣️.json",
  };
  const originals = { stdio: JSON.parse(readFileSync(join(repoRoot, sourcePaths.stdio), "utf8")), gis: JSON.parse(readFileSync(join(repoRoot, sourcePaths.gis), "utf8")) };
  const schemas = { stdio: hubSchemaExport(repoRoot, "schema://hub.compositions.stdio.catalog/NativeCodecFactories"), gis: hubSchemaExport(repoRoot, "schema://hub.compositions.gis/GisNativeCodecs") };
  const artifactRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
  assert(artifactRoot !== undefined && artifactRoot.includes("🗑️generated"));
  mkdirSync(artifactRoot, { recursive: true });
  const evidence = mkdtempSync(join(artifactRoot, "codec-source-"));
  let expected: string | undefined, generation: string | undefined;
  const profile = JSON.parse(readFileSync(join(root, "../🧬️stdio-gis-bootstrap/🔣️.json"), "utf8")).profile;
  for (const test of fixture.cases) {
    const input = structuredClone(originals);
    if (test.change === "permuted") {
      input.stdio.receipts.reverse();
      input.gis.receipts.reverse();
    }
    if (test.change === "invalid-hash") input.gis.receipts[0].protocolSha256 = "zz";
    if (test.change === "zero-hash") input.gis.receipts[0].protocolSha256 = "00".repeat(32);
    if (test.change === "duplicate-stdio") input.stdio.receipts[1] = structuredClone(input.stdio.receipts[0]);
    if (test.change === "duplicate-gis") input.gis.receipts[1] = structuredClone(input.gis.receipts[0]);
    if (test.change === "unknown-root") input.stdio.extra = true;
    if (test.change === "unknown-row") input.gis.receipts[0].extra = true;
    if (test.change === "foreign-package") input.stdio.package_id = "semio:foreign";
    if (test.change === "crossed-gis-schema") input.gis.receipts[0].schema = "gis.terrain";
    if (test.change === "zero-pack-schema-hash") input.gis.receipts[0].packSchemaHash = "00".repeat(32);
    if (test.change === "foreign-version") input.gis.packageVersion = "99.0.0";
    assert.equal(Boolean(schemas.stdio(input.stdio) && schemas.gis(input.gis)), test.schemaAccepted, test.change);
    const testRoot = join(evidence, test.change);
    for (const plugin of ["stdio", "gis"] as const) {
      const path = join(testRoot, sourcePaths[plugin]);
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, JSON.stringify(input[plugin]));
    }
    if (test.change === "invalid-utf8") writeFileSync(join(testRoot, sourcePaths.gis), Buffer.from([0xff]));
    if (test.change === "oversize") truncateSync(join(testRoot, sourcePaths.gis), fixture.maximumSourceBytes + 1);
    let captured = false;
    const check = (stage?: string) => {
      if (test.change === "cancelled") throw new Error("codec capture cancelled");
      if (test.change === "replaced-source" && stage === "project-codecs" && !captured) {
        captured = true;
        for (const plugin of ["stdio", "gis"] as const) writeFileSync(join(testRoot, sourcePaths[plugin]), "replaced source");
      }
    };
    if (!test.accepted) {
      assert.throws(() => captureTrustedBootstrapCodecsV1(testRoot, check), /codec|build input|UTF-8|encoded data/);
      continue;
    }
    const result = captureTrustedBootstrapCodecsV1(testRoot, check);
    assert(Object.isFrozen(result) && Object.isFrozen(result.codecs));
    for (const rows of Object.values(result.codecs)) {
      assert(Object.isFrozen(rows));
      for (const row of rows) assert(Object.isFrozen(row));
    }
    const canonical = JSON.stringify(result);
    const bytes = trustedBootstrapProfileEncoding(profile, result.codecs);
    const digest = await webSha256Hex(bytes);
    assert.equal(createHash("sha256").update(bytes).digest("hex"), digest);
    if (expected === undefined) {
      expected = canonical;
      generation = digest;
    }
    assert.equal(canonical, expected, test.change);
    assert.equal(digest, generation, test.change);
    if (test.change === "replaced-source") assert(captured);
  }
  console.log(`trusted-codec-source: AJV=3 WebCrypto=1 cases=${fixture.cases.length} evidence=${evidence}`);
}

type TrustedBootstrapGenerationReceiptV1 = Readonly<{
  identity: TrustedBootstrapIdentityV1;
  dependencies: readonly TrustedBootstrapIdentityV1[];
  component: Readonly<{ byteLength: number; sha256: string }>;
  descriptor: Readonly<{ byteLength: number; sha256: string }>;
  executionProtocol: Readonly<DocumentExecutionProtocolV1>;
  browserActor: TrustedBootstrapBrowserActorV1;
  pluginModule: TrustedBootstrapPluginModuleRecordV1;
}>;

/** 🧩️ Where a package record finds its plugin module manifest: `TrustedBundlePluginModuleV1`. */
type TrustedBootstrapPluginModuleRecordV1 = Readonly<{ path: string; byteLength: number; sha256: string; blake3: string }>;

/** 🧩️ Admits one `TrustedBundlePluginModuleV1` record at its own package's fixed manifest path. */
function trustedBootstrapPluginModuleRecordV1(candidate: unknown, pluginId: string): TrustedBootstrapPluginModuleRecordV1 {
  const row = documentOpenNeutralObject(candidate, ["path", "byteLength", "sha256", "blake3"]);
  if (row.path !== trustedBootstrapPluginModuleManifestPath(pluginId) || !Number.isSafeInteger(row.byteLength) || (row.byteLength as number) <= 0 || (row.byteLength as number) > TRUSTED_PLUGIN_MODULE_BUNDLE_MAX_BYTES || !/^[0-9a-f]{64}$/u.test(String(row.sha256)) || !/^[0-9a-f]{64}$/u.test(String(row.blake3)))
    throw new Error("trusted plugin module record is not its package's exact manifest");
  return Object.freeze({ path: row.path as string, byteLength: row.byteLength as number, sha256: row.sha256 as string, blake3: row.blake3 as string });
}

/** 🧩️ The generation-relative manifest path of one package's plugin module. */
function trustedBootstrapPluginModuleManifestPath(pluginId: string): string {
  return `packages/${pluginId}/plugin-module.json`;
}

/** 🗃️ The generation-relative content-addressed path of one plugin module file. */
function trustedBootstrapPluginModuleBlobPath(sha256: string): string {
  return `plugin-modules/${sha256}`;
}

/** 🧬️ Frames one plugin module record into the generation exactly as `trusted_profile_generation` does. */
function trustedBootstrapPluginModuleEncoding(record: TrustedBootstrapPluginModuleRecordV1): Buffer {
  const length = Buffer.alloc(8);
  length.writeBigUInt64BE(BigInt(record.byteLength));
  return Buffer.concat([trustedBootstrapField(record.path), length, trustedBootstrapField(Buffer.from(record.sha256, "hex")), trustedBootstrapField(Buffer.from(record.blake3, "hex"))]);
}

/** 🧩️ Reads one generation's plugin module manifest, bound to its record and its package's digests. */
function trustedBootstrapReadPluginModule(root: string, receipt: TrustedBootstrapGenerationReceiptV1, check: () => void): TrustedPluginModuleBundleV1 {
  const bytes = readStableBuildFile(join(root, receipt.pluginModule.path), TRUSTED_PLUGIN_MODULE_BUNDLE_MAX_BYTES, { remaining: TRUSTED_PLUGIN_MODULE_BUNDLE_MAX_BYTES }, check);
  if (bytes.byteLength !== receipt.pluginModule.byteLength || createHash("sha256").update(bytes).digest("hex") !== receipt.pluginModule.sha256 || blake3Hex(bytes) !== receipt.pluginModule.blake3) throw new Error("generation plugin module manifest differs from its record");
  return decodeTrustedPluginModuleBundleV1(bytes, { ...receipt.identity, componentSha256: receipt.component.sha256, descriptorByteSha256: receipt.descriptor.sha256 });
}

/**
 * 🧳️ Carries one package's plugin module from a verified source generation into a new stage: every file is
 * reread and checked against its manifest, and the packed and JSON descriptors are replaced by the package's
 * (possibly rewritten) `descriptor`, so the carried module is derived from exactly the package it ships with.
 */
function trustedBootstrapCarryPluginModule(sourceRoot: string, stageRoot: string, sourceReceipt: TrustedBootstrapGenerationReceiptV1, record: any, descriptor: Uint8Array, check: () => void): TrustedBootstrapPluginModuleRecordV1 {
  const source = trustedBootstrapReadPluginModule(sourceRoot, sourceReceipt, check);
  const replacements = new Map<string, Uint8Array>([
    [`${source.moduleDirectory}/${TRUSTED_PLUGIN_MODULE_DESCRIPTOR_PACK_FILE}`, descriptor],
    [`${source.moduleDirectory}/${TRUSTED_PLUGIN_MODULE_DESCRIPTOR_JSON_FILE}`, Buffer.from(`${JSON.stringify(packValueToExactJson(decodePackValue(descriptor)), null, 2)}\n`, "utf8")],
  ]);
  const blobs = join(stageRoot, "plugin-modules");
  mkdirSync(blobs, { recursive: true, mode: 0o700 });
  const files = source.files.map((file) => {
    const bytes = replacements.get(file.path) ?? readStableBuildFile(join(sourceRoot, trustedBootstrapPluginModuleBlobPath(file.sha256)), file.byteLength, { remaining: file.byteLength }, check);
    const carried = { path: file.path, byteLength: bytes.byteLength, sha256: createHash("sha256").update(bytes).digest("hex"), blake3: blake3Hex(bytes) };
    if (!replacements.has(file.path) && (carried.sha256 !== file.sha256 || carried.blake3 !== file.blake3)) throw new Error("trusted rotation plugin module file differs from its manifest");
    if (!existsSync(join(blobs, carried.sha256))) trustedBootstrapWriteNew(join(blobs, carried.sha256), bytes, check);
    return carried;
  });
  const descriptorByteSha256 = createHash("sha256").update(descriptor).digest("hex");
  const manifest = encodeTrustedPluginModuleBundleV1({ ...source, sourceComponentSha256: record.component.sha256, sourceDescriptorByteSha256: descriptorByteSha256, files });
  decodeTrustedPluginModuleBundleV1(manifest, { pluginId: record.pluginId, packageId: record.packageId, version: record.version, componentSha256: record.component.sha256, descriptorByteSha256 });
  trustedBootstrapWriteNew(join(stageRoot, trustedBootstrapPluginModuleManifestPath(record.pluginId)), manifest, check);
  return Object.freeze({ path: trustedBootstrapPluginModuleManifestPath(record.pluginId), byteLength: manifest.byteLength, sha256: createHash("sha256").update(manifest).digest("hex"), blake3: blake3Hex(manifest) });
}

/** 🛑️ An abort signal for one child process that follows the bootstrap's own cancellation and deadline. */
function trustedBootstrapAbortSignal(control: FreshBuildControlV1): { readonly signal: AbortSignal; close(): void } {
  const abort = new AbortController();
  const poll = setInterval(() => {
    if (control.cancelled() || control.remainingMs() <= 0) abort.abort(new Error("trusted catalog build cancelled"));
  }, 250);
  return { signal: abort.signal, close: () => clearInterval(poll) };
}

/**
 * 🧩️ Materializes one package's browser plugin module from its own fresh component and staged descriptor —
 * host shim, jco component module, core Wasm (never re-optimized, so it stays the exact module the
 * descriptor's `coreWasmSha256` names), bridge, both descriptor forms and the vendored imports — and stages
 * it content-addressed in the generation: every file once under `plugin-modules/<sha256>` (shared across
 * packages), the canonical manifest at `packages/<plugin>/plugin-module.json`.
 */
async function trustedBootstrapPluginModuleV1(repoRoot: string, request: Readonly<{ pluginId: string; outputName: string }>, stage: string, stageRoot: string, work: string, receipt: FreshComponentReceiptV1, control: FreshBuildControlV1, check: () => void): Promise<TrustedBootstrapPluginModuleRecordV1> {
  const moduleRoot = join(work, "plugin-module");
  const directory = moduleDirectoryName(request.pluginId, COMPONENT_MODULE_DIRECTORIES);
  const moduleDir = join(moduleRoot, directory);
  const vendor = join(moduleRoot, PREVIEW2_VENDOR_RELATIVE);
  mkdirSync(moduleDir, { recursive: true, mode: 0o700 });
  ensurePreview2ShimVendorAt(vendor, repoRoot);
  if (!ensureGuestSlimTypstFontsAt(moduleRoot, repoRoot)) throw new Error("trusted plugin module needs the staged guestslim typst font seed");
  const descriptor = trustedBootstrapReadRegular(join(stage, "descriptor.semio"), DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES, `fresh ${request.pluginId} descriptor for its plugin module`, check);
  if (descriptor.byteLength !== receipt.descriptor.byteLength || createHash("sha256").update(descriptor).digest("hex") !== receipt.descriptor.sha256) throw new Error("fresh descriptor differs from its receipt before plugin module materialization");
  const componentBase = `${request.outputName.slice(0, -".wasm".length)}_component`;
  writeFileSync(join(moduleDir, PLUGIN_HOST_SHIM_FILE), hostShimSource());
  const abort = trustedBootstrapAbortSignal(control);
  try {
    await transpilePluginComponentAsync(join(stage, "component.wasm"), moduleDir, componentBase, { repoRoot, preview2VendorDir: vendor, signal: abort.signal, optimize: false });
  } finally {
    abort.close();
  }
  check();
  writeFileSync(join(moduleDir, MODULE_BRIDGE_FILE), pluginComponentBridgeSource(componentBase, request.outputName));
  writeFileSync(join(moduleDir, TRUSTED_PLUGIN_MODULE_DESCRIPTOR_JSON_FILE), `${JSON.stringify(packValueToExactJson(decodePackValue(descriptor)), null, 2)}\n`);
  writeFileSync(join(moduleDir, TRUSTED_PLUGIN_MODULE_DESCRIPTOR_PACK_FILE), descriptor);
  rmSync(join(moduleDir, `${componentBase}.d.ts`), { force: true });
  rmSync(join(moduleDir, "interfaces"), { recursive: true, force: true });
  const core = readStableBuildFile(join(moduleDir, `${componentBase}.core.wasm`), TRUSTED_PLUGIN_MODULE_FILE_MAX_BYTES, { remaining: TRUSTED_PLUGIN_MODULE_FILE_MAX_BYTES }, check);
  if (createHash("sha256").update(core).digest("hex") !== receipt.coreSha256) throw new Error(`trusted ${request.pluginId} plugin module core differs from the core its descriptor names`);
  const walk = (relative: string): string[] =>
    readdirSync(join(moduleRoot, relative), { withFileTypes: true }).flatMap((entry) => {
      const path = relative ? `${relative}/${entry.name}` : entry.name;
      if (entry.isDirectory()) return walk(path);
      if (!entry.isFile() || entry.name.startsWith(".")) throw new Error(`trusted plugin module carries a non-file ${path}`);
      return [path];
    });
  const blobs = join(stageRoot, "plugin-modules");
  mkdirSync(blobs, { recursive: true, mode: 0o700 });
  const files = walk("")
    .sort(utf8OrderV1)
    .map((path) => {
      check();
      const bytes = readStableBuildFile(join(moduleRoot, path), TRUSTED_PLUGIN_MODULE_FILE_MAX_BYTES, { remaining: TRUSTED_PLUGIN_MODULE_FILE_MAX_BYTES }, check);
      const file = { path, byteLength: bytes.byteLength, sha256: createHash("sha256").update(bytes).digest("hex"), blake3: blake3Hex(bytes) };
      if (!existsSync(join(blobs, file.sha256))) trustedBootstrapWriteNew(join(blobs, file.sha256), bytes, check);
      return file;
    });
  const bundle = {
    schema: TRUSTED_PLUGIN_MODULE_SCHEMA,
    pluginId: request.pluginId,
    packageId: receipt.packageId,
    version: receipt.version,
    sourceComponentSha256: receipt.component.sha256,
    sourceDescriptorByteSha256: receipt.descriptor.sha256,
    moduleDirectory: directory,
    entry: `${directory}/${MODULE_BRIDGE_FILE}`,
    files,
  };
  const manifest = encodeTrustedPluginModuleBundleV1(bundle);
  decodeTrustedPluginModuleBundleV1(manifest, { pluginId: request.pluginId, packageId: receipt.packageId, version: receipt.version, componentSha256: receipt.component.sha256, descriptorByteSha256: receipt.descriptor.sha256 });
  trustedBootstrapWriteNew(join(stage, "plugin-module.json"), manifest, check);
  trustedBootstrapFsyncDirectory(blobs);
  rmSync(moduleRoot, { recursive: true, force: true });
  return Object.freeze({ path: trustedBootstrapPluginModuleManifestPath(request.pluginId), byteLength: manifest.byteLength, sha256: createHash("sha256").update(manifest).digest("hex"), blake3: blake3Hex(manifest) });
}

/** 🧷️ Retains the exact metadata needed to rebind every staged descriptor to its bundle. */
function trustedBootstrapGenerationReceipt(record: any): TrustedBootstrapGenerationReceiptV1 {
  const identity = trustedBootstrapIdentity({ pluginId: record.pluginId, packageId: record.packageId, version: record.version });
  return Object.freeze({
    identity, dependencies: trustedBootstrapDependencies(record.dependencies),
    component: Object.freeze({ byteLength: record.component.byteLength, sha256: record.component.sha256 }),
    descriptor: Object.freeze({ byteLength: record.descriptor.byteLength, sha256: record.descriptor.sha256 }),
    executionProtocol: trustedBootstrapExecutionProtocol(record.executionProtocol),
    // 🖥️ The renderer this receipt validates the actor against comes from the actor's own kind, not
    // from the package's name: this helper is re-run on an already-projected receipt (which carries
    // no target list) as well as on a bundle record. That a package with open targets must carry a
    // wasm actor at all is enforced where the target list IS in hand —
    // `trustedBootstrapProfileEncoding`, through `trustedBootstrapPackageRenderer`.
    browserActor: trustedBootstrapBrowserActorV1(record.browserActor, { componentSha256: record.component.sha256, descriptorByteSha256: record.descriptor.sha256 }, record.browserActor?.kind === "closed-browser-actor" ? "wasm" : "react"),
    pluginModule: trustedBootstrapPluginModuleRecordV1(record.pluginModule, identity.pluginId),
  });
}

/** 🧱️ Revalidates every fixed generation input and its path identity immediately before publication. */
function trustedBootstrapVerifyGeneration(root: string, bundle: Uint8Array, receipts: ReadonlyMap<string, TrustedBootstrapGenerationReceiptV1>, check: (phase?: string) => void): void {
  try {
    check();
    if (receipts.size === 0 || !receipts.has("stdio") || !bundle.byteLength || bundle.byteLength > 4 * 1024 * 1024) throw new Error("generation input closure differs");
    const packages = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bundle)).packages;
    if (!Array.isArray(packages) || packages.length !== receipts.size) throw new Error("generation bundle dependency closure differs");
    const bundleReceipts = new Map(packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)]));
    if (bundleReceipts.size !== receipts.size) throw new Error("generation bundle dependency identity is duplicated");
    const selected = trustedBootstrapDependencies([...bundleReceipts.values()].map((receipt) => receipt.identity));
    for (const [plugin, receipt] of receipts) {
      const expected = bundleReceipts.get(plugin);
      if (!expected || JSON.stringify(expected) !== JSON.stringify(trustedBootstrapGenerationReceipt({ ...receipt.identity, ...receipt }))) throw new Error("generation bundle metadata differs from its retained receipt");
    }
    // 📁️ The published tree is EXACTLY what the bundle's own package records name: one directory per
    // selected package, `browser/closed-actor.mjs` exactly where a record carries a closed actor and
    // nowhere else. It is derived rather than spelled so a third package is verified as strictly as
    // the first two (ticket 26/09/18 slice TC3c).
    const plugins = [...bundleReceipts.keys()].sort();
    const carriesActor = (plugin: string): boolean => bundleReceipts.get(plugin)!.browserActor.kind === "closed-browser-actor";
    const moduleFiles = new Map<string, Readonly<{ byteLength: number; sha256: string }>>();
    for (const plugin of plugins) {
      for (const file of trustedBootstrapReadPluginModule(root, receipts.get(plugin)!, check).files) {
        const known = moduleFiles.get(file.sha256);
        if (known && known.byteLength !== file.byteLength) throw new Error("generation plugin modules disagree about one content address");
        moduleFiles.set(file.sha256, { byteLength: file.byteLength, sha256: file.sha256 });
      }
    }
    const directories: (readonly [string, readonly string[]])[] = [
      [root, ["packages", "plugin-modules", "trusted-catalog.json"]],
      [join(root, "packages"), plugins],
      [join(root, "plugin-modules"), [...moduleFiles.keys()]],
    ];
    for (const plugin of plugins) {
      directories.push([join(root, "packages", plugin), carriesActor(plugin) ? ["browser", "component.wasm", "descriptor.semio", "plugin-module.json"] : ["component.wasm", "descriptor.semio", "plugin-module.json"]]);
      if (carriesActor(plugin)) directories.push([join(root, "packages", plugin, "browser"), ["closed-actor.mjs"]]);
    }
    const identities = new Map<string, Stats>();
    for (const [path, entries] of directories) {
      check();
      const info = lstatSync(path);
      if (info.isSymbolicLink() || !info.isDirectory() || JSON.stringify(readdirSync(path).sort()) !== JSON.stringify([...entries].sort())) throw new Error("generation directory is not the exact regular closure");
      identities.set(path, info);
    }
    const files = [{ path: join(root, "trusted-catalog.json"), byteLength: bundle.byteLength, sha256: createHash("sha256").update(bundle).digest("hex"), maximum: 4 * 1024 * 1024 }];
    const descriptorReceipts = new Map<string, TrustedBootstrapGenerationReceiptV1>();
    for (const plugin of plugins) {
      const receipt = receipts.get(plugin)!;
      descriptorReceipts.set(join(root, "packages", plugin, "descriptor.semio"), receipt);
      files.push({ path: join(root, "packages", plugin, "component.wasm"), byteLength: receipt.component.byteLength, sha256: receipt.component.sha256, maximum: DOCUMENT_EXECUTION_TARGET_COMPONENT_MAX_BYTES });
      files.push({ path: join(root, "packages", plugin, "descriptor.semio"), byteLength: receipt.descriptor.byteLength, sha256: receipt.descriptor.sha256, maximum: DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES });
      files.push({ path: join(root, receipt.pluginModule.path), byteLength: receipt.pluginModule.byteLength, sha256: receipt.pluginModule.sha256, maximum: TRUSTED_PLUGIN_MODULE_BUNDLE_MAX_BYTES });
      const actor = trustedBootstrapBrowserActorV1(receipt.browserActor, { componentSha256: receipt.component.sha256, descriptorByteSha256: receipt.descriptor.sha256 }, carriesActor(plugin) ? "wasm" : "react");
      if (actor.kind === "closed-browser-actor") {
        if (actor.path !== `packages/${plugin}/browser/closed-actor.mjs`) throw new Error("generation actor path differs from its own package closure");
        files.push({ path: join(root, "packages", plugin, "browser", "closed-actor.mjs"), byteLength: actor.byteLength, sha256: actor.sha256, maximum: 67_108_864 });
      }
    }
    for (const file of moduleFiles.values()) files.push({ path: join(root, trustedBootstrapPluginModuleBlobPath(file.sha256)), byteLength: file.byteLength, sha256: file.sha256, maximum: TRUSTED_PLUGIN_MODULE_FILE_MAX_BYTES });
    const admission = { remaining: files.reduce((sum, file) => sum + file.maximum, 0) };
    for (const file of files) {
      if (!Number.isSafeInteger(file.byteLength) || file.byteLength <= 0 || file.byteLength > file.maximum || !/^[0-9a-f]{64}$/u.test(file.sha256)) throw new Error("generation file receipt is not bounded");
      identities.set(file.path, lstatSync(file.path));
      const bytes = readStableBuildFile(file.path, file.maximum, admission, check);
      try {
        if (bytes.byteLength !== file.byteLength || createHash("sha256").update(bytes).digest("hex") !== file.sha256) throw new Error("generation bytes differ from their verified receipt");
        const receipt = descriptorReceipts.get(file.path);
        if (receipt) {
          const claims = trustedBootstrapDescriptorClaims(bytes);
          const dependencies = trustedBootstrapResolveDependencies(claims, selected);
          if (JSON.stringify(claims.identity) !== JSON.stringify(receipt.identity) || claims.executionProtocol.appChannelVersion !== receipt.executionProtocol.appChannelVersion || !trustedBootstrapDependencyEncoding(dependencies).equals(trustedBootstrapDependencyEncoding(receipt.dependencies))) throw new Error("generation descriptor identity, protocol or dependencies differ from its receipt");
        }
      } finally {
        bytes.fill(0);
      }
    }
    check("identity");
    for (const [path, before] of identities) {
      const after = lstatSync(path);
      if (after.isSymbolicLink() || before.dev !== after.dev || before.ino !== after.ino || before.mode !== after.mode || before.size !== after.size || before.mtimeMs !== after.mtimeMs || before.ctimeMs !== after.ctimeMs)
        throw new Error("generation path changed across the final fence");
    }
  } catch (error) {
    throw new Error(`trusted generation fence: ${(error as Error).message}`);
  }
}

/** 🧩️ One never-executed fixture plugin module: its entry, both descriptor forms (the packed one the package's
 * own descriptor) and one vendored import — the TS twin of the hub's `fixture_plugin_module_files`. */
type TrustedBootstrapFixturePluginModuleV1 = Readonly<{ record: TrustedBootstrapPluginModuleRecordV1; manifest: Uint8Array; blobs: ReadonlyMap<string, Uint8Array> }>;

function trustedBootstrapFixturePluginModule(identity: Readonly<{ pluginId: string; packageId: string; version: string }>, componentSha256: string, descriptor: Uint8Array): TrustedBootstrapFixturePluginModuleV1 {
  const utf8 = (text: string) => Buffer.from(text, "utf8");
  const contents: [string, Uint8Array][] = [
    [`${identity.pluginId}/${MODULE_BRIDGE_FILE}`, utf8("export async function createActorApi() {}\n")],
    [`${identity.pluginId}/${TRUSTED_PLUGIN_MODULE_DESCRIPTOR_JSON_FILE}`, utf8(JSON.stringify({ manifest: { pluginId: identity.pluginId } }))],
    [`${identity.pluginId}/${TRUSTED_PLUGIN_MODULE_DESCRIPTOR_PACK_FILE}`, descriptor],
    [`${PREVIEW2_VENDOR_RELATIVE}/io.js`, utf8("export const streams = {};\n")],
  ];
  const blobs = new Map<string, Uint8Array>();
  const files = contents
    .sort(([left], [right]) => utf8OrderV1(left, right))
    .map(([path, bytes]) => {
      const sha256 = createHash("sha256").update(bytes).digest("hex");
      blobs.set(sha256, bytes);
      return { path, byteLength: bytes.byteLength, sha256, blake3: blake3Hex(bytes) };
    });
  const descriptorByteSha256 = createHash("sha256").update(descriptor).digest("hex");
  const manifest = encodeTrustedPluginModuleBundleV1({ schema: TRUSTED_PLUGIN_MODULE_SCHEMA, ...identity, sourceComponentSha256: componentSha256, sourceDescriptorByteSha256: descriptorByteSha256, moduleDirectory: identity.pluginId, entry: `${identity.pluginId}/${MODULE_BRIDGE_FILE}`, files });
  decodeTrustedPluginModuleBundleV1(manifest, { ...identity, componentSha256, descriptorByteSha256 });
  return Object.freeze({ record: Object.freeze({ path: trustedBootstrapPluginModuleManifestPath(identity.pluginId), byteLength: manifest.byteLength, sha256: createHash("sha256").update(manifest).digest("hex"), blake3: blake3Hex(manifest) }), manifest, blobs });
}

/** 🧩️ Writes one fixture plugin module beneath a generation root, replacing an earlier one's manifest. */
function trustedBootstrapWriteFixturePluginModule(root: string, module: TrustedBootstrapFixturePluginModuleV1): void {
  mkdirSync(join(root, "plugin-modules"), { recursive: true });
  mkdirSync(dirname(join(root, module.record.path)), { recursive: true });
  writeFileSync(join(root, module.record.path), module.manifest);
  for (const [sha256, bytes] of module.blobs) writeFileSync(join(root, trustedBootstrapPluginModuleBlobPath(sha256)), bytes);
}

/** 🧫️ Constructs only neutral descriptor projections for physical publication-fence laws. */
function trustedBootstrapStageFixturePackages(fixture: any, actor: any, component: Uint8Array): { packages: any[]; descriptors: Map<string, Buffer>; modules: Map<string, TrustedBootstrapFixturePluginModuleV1> } {
  const descriptors = new Map(["gis", "stdio"].map((plugin) => [plugin, Buffer.from(encodePackValue(fixture.descriptors[plugin]))]));
  const identity = (bytes: Uint8Array) => ({ byteLength: bytes.byteLength, sha256: createHash("sha256").update(bytes).digest("hex") });
  const records = ["gis", "stdio"].map((pluginId) => {
    const source = { component: identity(component), descriptor: identity(descriptors.get(pluginId)!) };
    return {
      pluginId, packageId: `semio:${pluginId}`, version: "0.1.0", ...source,
      dependencies: pluginId === "gis" ? [{ pluginId: "stdio", packageId: "semio:stdio", version: "0.1.0" }] : [],
      executionProtocol: fixture.executionProtocol,
      browserActor: pluginId === "gis" ? { ...actor, path: "packages/gis/browser/closed-actor.mjs", sourceComponentSha256: source.component.sha256, sourceDescriptorByteSha256: source.descriptor.sha256 } : { kind: "none" },
    };
  });
  const modules = new Map(records.map((record) => [record.pluginId, trustedBootstrapFixturePluginModule(record, record.component.sha256, descriptors.get(record.pluginId)!)]));
  const packages = records.map((record) => ({ ...record, pluginModule: modules.get(record.pluginId)!.record }));
  return { packages, descriptors, modules };
}

/** 🧪️ Exercises the actual pre-publication file fence against independent digest oracles. */
async function proveTrustedGenerationStageFixture(repoRoot: string): Promise<void> {
  const assert: (typeof import("node:assert"))["strict"] = (await import("node:assert/strict")).default;
  const { symlinkSync, truncateSync, writeFileSync } = await import("node:fs");
  const root = join(repoRoot, "🌎️hub/🗿️artifact-authority/🔏️trusted-catalog/🧫️fixtures/🧱️generation-stage");
  const fixture = JSON.parse(readFileSync(join(root, "🔣️.json"), "utf8"));
  const validateProtocol = hubSchemaExport(repoRoot, "schema://hub.artifact-authority.trusted-catalog/TrustedBundleExecutionProtocolV1");
  assert.deepEqual(Object.keys(fixture), ["schema", "componentHex", "descriptors", "executionProtocol", "cases"]);
  assert.equal(fixture.schema, "semio.hub.generation-stage.v1");
  assert.equal(fixture.componentHex, "616263");
  assert.deepEqual(fixture.descriptors, {
    gis: { packageId: "semio:gis", manifest: { pluginId: "gis", version: "0.1.0", dependencies: [{ pluginId: "stdio", version: "=0.1.0" }] }, executionProtocol: { appChannelVersion: DOCUMENT_EXECUTION_PROTOCOL_APP_CHANNEL_VERSION_V1 } },
    stdio: { packageId: "semio:stdio", manifest: { pluginId: "stdio", version: "0.1.0", dependencies: [] }, executionProtocol: { appChannelVersion: DOCUMENT_EXECUTION_PROTOCOL_APP_CHANNEL_VERSION_V1 } },
  });
  assert.deepEqual(fixture.executionProtocol, { appChannelVersion: DOCUMENT_EXECUTION_PROTOCOL_APP_CHANNEL_VERSION_V1 });
  for (const protocol of [fixture.executionProtocol, fixture.descriptors.gis.executionProtocol, fixture.descriptors.stdio.executionProtocol]) assert(validateProtocol(protocol), "generation-stage execution protocol must satisfy the scope-owned contract");
  assert.deepEqual(fixture.cases.map((row: any) => row.change), [
    "none", "component", "descriptor", "bundle", "extra-file", "missing-file", "symlink-file", "symlink-directory", "post-read-component",
    "oversize-component", "cancelled", "receipt-path", "actor", "actor-source", "actor-path", "missing-actor", "oversize-actor", "post-read-actor",
    "actor-symlink", "missing-protocol", "unsupported-protocol", "receipt-protocol", "missing-dependency", "receipt-dependency", "bundle-dependency",
    "wrong-package", "nonexact-dependency", "duplicate-dependency", "plugin-module-file", "plugin-module-manifest", "plugin-module-missing-file",
    "plugin-module-extra-file", "post-read-plugin-module-file",
  ]);
  assert.deepEqual(fixture.cases.filter((row: any) => row.accepted).map((row: any) => row.change), ["none", "receipt-path"]);
  const artifactRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
  assert(artifactRoot !== undefined && artifactRoot.includes("🗑️generated"));
  mkdirSync(artifactRoot, { recursive: true });
  const evidence = mkdtempSync(join(artifactRoot, "generation-stage-"));
  const component = Buffer.from(fixture.componentHex, "hex");
  const identity = async (bytes: Uint8Array) => ({ byteLength: bytes.byteLength, sha256: await webSha256Hex(bytes) });
  const actorFixture = JSON.parse(readFileSync(join(root, "../🌐️browser-actor/🔣️.json"), "utf8"));
  const { packages, descriptors } = trustedBootstrapStageFixturePackages(fixture, actorFixture.closed, component);
  const receipts = new Map(packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)]));
  const moduleBlob = (stage: string, plugin: string, suffix: string) => {
    const manifest = JSON.parse(readFileSync(join(stage, "packages", plugin, "plugin-module.json"), "utf8"));
    return join(stage, "plugin-modules", manifest.files.find((file: any) => file.path.endsWith(suffix)).sha256);
  };
  for (const record of packages) {
    assert.deepEqual(record.component, await identity(component));
    assert.deepEqual(record.descriptor, await identity(descriptors.get(record.pluginId)!));
  }
  for (const test of fixture.cases) {
    const caseReceipts = structuredClone(receipts);
    const casePackages = structuredClone(packages);
    const caseDescriptors = new Map(descriptors);
    const stage = join(evidence, test.change);
    for (const plugin of ["gis", "stdio"]) {
      mkdirSync(join(stage, "packages", plugin), { recursive: true });
      writeFileSync(join(stage, "packages", plugin, "component.wasm"), component);
      writeFileSync(join(stage, "packages", plugin, "descriptor.semio"), descriptors.get(plugin)!);
    }
    mkdirSync(join(stage, "packages/gis/browser"));
    const actorPath = join(stage, "packages/gis/browser/closed-actor.mjs");
    writeFileSync(actorPath, component);
    const componentPath = join(stage, "packages/gis/component.wasm");
    if (test.change === "component") writeFileSync(componentPath, "xbc");
    if (test.change === "descriptor") writeFileSync(join(stage, "packages/stdio/descriptor.semio"), "xef");
    if (test.change === "extra-file") writeFileSync(join(stage, "extra"), "extra");
    if (test.change === "missing-file") rmSync(componentPath);
    if (test.change === "symlink-file") {
      rmSync(componentPath);
      symlinkSync(join(stage, process.platform === "win32" ? "packages/stdio" : "packages/stdio/component.wasm"), componentPath, process.platform === "win32" ? "junction" : "file");
    }
    if (test.change === "symlink-directory") {
      renameSync(join(stage, "packages/gis"), join(evidence, "external-gis"));
      symlinkSync(join(evidence, "external-gis"), join(stage, "packages/gis"), "junction");
    }
    if (test.change === "oversize-component") truncateSync(componentPath, DOCUMENT_EXECUTION_TARGET_COMPONENT_MAX_BYTES + 1);
    if (test.change === "receipt-path") Object.assign(caseReceipts.get("gis")!.component, { path: "untrusted-receipt-cannot-select-path" });
    if (test.change === "receipt-protocol") Object.assign(caseReceipts.get("stdio")!, { executionProtocol: { appChannelVersion: 13 } });
    if (test.change === "receipt-dependency") Object.assign(caseReceipts.get("gis")!, { dependencies: [] });
    if (test.change === "bundle-dependency") casePackages[0].dependencies = [];
    if (["missing-dependency", "wrong-package", "nonexact-dependency", "duplicate-dependency"].includes(test.change)) {
      const changed = structuredClone(fixture.descriptors.gis);
      if (test.change === "missing-dependency") changed.manifest.dependencies = [];
      if (test.change === "wrong-package") changed.packageId = "semio:foreign";
      if (test.change === "nonexact-dependency") changed.manifest.dependencies[0].version = "^0.1.0";
      if (test.change === "duplicate-dependency") changed.manifest.dependencies.push({ ...changed.manifest.dependencies[0] });
      const bytes = Buffer.from(encodePackValue(changed));
      const digest = await identity(bytes);
      caseDescriptors.set("gis", bytes);
      writeFileSync(join(stage, "packages/gis/descriptor.semio"), bytes);
      Object.assign(casePackages[0], { descriptor: digest, browserActor: { ...casePackages[0].browserActor, sourceDescriptorByteSha256: digest.sha256 } });
      caseReceipts.set("gis", trustedBootstrapGenerationReceipt(casePackages[0]));
    }
    if (test.change === "missing-protocol" || test.change === "unsupported-protocol") {
      const changed = Buffer.from(encodePackValue(test.change === "missing-protocol" ? {} : { executionProtocol: { appChannelVersion: 13 } }));
      writeFileSync(join(stage, "packages/stdio/descriptor.semio"), changed);
      caseDescriptors.set("stdio", changed);
      Object.assign(caseReceipts.get("stdio")!, { descriptor: await identity(changed) });
      casePackages[1].descriptor = await identity(changed);
    }
    if (test.change === "actor") writeFileSync(actorPath, "xbc");
    if (test.change === "actor-source") Object.assign(caseReceipts.get("gis")!.browserActor, { sourceDescriptorByteSha256: "42".repeat(32) });
    if (test.change === "actor-path") Object.assign(caseReceipts.get("gis")!.browserActor, { path: "packages/gis/component.wasm" });
    if (test.change === "missing-actor") rmSync(actorPath);
    if (test.change === "oversize-actor") truncateSync(actorPath, 67_108_865);
    if (test.change === "actor-symlink") {
      rmSync(actorPath);
      symlinkSync(join(stage, process.platform === "win32" ? "packages/stdio" : "packages/stdio/component.wasm"), actorPath, process.platform === "win32" ? "junction" : "file");
    }
    for (const [index, plugin] of ["gis", "stdio"].entries()) {
      if (!existsSync(join(stage, "packages", plugin))) continue;
      const module = trustedBootstrapFixturePluginModule(casePackages[index], casePackages[index].component.sha256, caseDescriptors.get(plugin)!);
      trustedBootstrapWriteFixturePluginModule(stage, module);
      casePackages[index].pluginModule = module.record;
      caseReceipts.set(plugin, { ...caseReceipts.get(plugin)!, pluginModule: module.record });
    }
    if (test.change === "plugin-module-file") writeFileSync(moduleBlob(stage, "gis", "bridge.js"), "export {};\n");
    if (test.change === "plugin-module-manifest") writeFileSync(join(stage, "packages/stdio/plugin-module.json"), "{}\n");
    if (test.change === "plugin-module-missing-file") rmSync(moduleBlob(stage, "stdio", "io.js"));
    if (test.change === "plugin-module-extra-file") writeFileSync(join(stage, "plugin-modules", "ab".repeat(32)), "unlisted");
    const pluginModuleFile = moduleBlob(stage, "gis", ".json");
    const bundle = Buffer.from(JSON.stringify({ neutral: true, packages: casePackages }) + "\n");
    writeFileSync(join(stage, "trusted-catalog.json"), test.change === "bundle" ? '{"neutral":false}' : bundle);
    let replaced = false,
      identityChecks = 0;
    const check = (phase?: string) => {
      if (identityChecks) throw new Error("generation checkpoint after the final identity fence began");
      if (phase === "identity") identityChecks++;
      if (test.change === "cancelled") throw new Error("generation stage cancelled");
      if (test.change === "post-read-component" && phase === "identity" && !replaced) {
        writeFileSync(componentPath, "xbc");
        replaced = true;
      }
      if (test.change === "post-read-actor" && phase === "identity" && !replaced) {
        writeFileSync(actorPath, "xbc");
        replaced = true;
      }
      if (test.change === "post-read-plugin-module-file" && phase === "identity" && !replaced) {
        writeFileSync(pluginModuleFile, "{}");
        replaced = true;
      }
    };
    if (test.accepted) {
      trustedBootstrapVerifyGeneration(stage, bundle, caseReceipts, check);
      assert.equal(identityChecks, 1);
    } else assert.throws(() => trustedBootstrapVerifyGeneration(stage, bundle, caseReceipts, check), /generation|build input/);
  }
  console.log(`trusted-generation-stage: scope-export=TrustedBundleExecutionProtocolV1 WebCrypto=1 cases=${fixture.cases.length} evidence=${evidence}`);
}

/** 📤️ Proves the publisher rechecks each receipt-bound leaf after candidate validation. */
async function proveTrustedPublicationFixture(repoRoot: string): Promise<void> {
  const assert: (typeof import("node:assert"))["strict"] = (await import("node:assert/strict")).default;
  const { writeFileSync } = await import("node:fs");
  const root = join(repoRoot, "🌎️hub/🗿️artifact-authority/🔏️trusted-catalog/🧫️fixtures/📤️publication");
  const fixture = JSON.parse(readFileSync(join(root, "🔣️.json"), "utf8"));
  assert.deepEqual(Object.keys(fixture), ["schema", "generationId", "profileId", "cases", "commandCases", "receiptCases"]);
  assert.equal(fixture.schema, "semio.hub.trusted-publication/v1");
  assert.equal(fixture.generationId, "aa".repeat(32));
  assert.equal(fixture.profileId, "publication-fixture");
  assert.deepEqual(fixture.cases, [
    { change: "none", accepted: true }, { change: "component", accepted: false }, { change: "descriptor", accepted: false },
    { change: "actor", accepted: false }, { change: "plugin-module", accepted: false }, { change: "bundle", accepted: false },
  ]);
  const command = JSON.parse(readFileSync(join(root, "📬️command.json"), "utf8"));
  const validateCommand = hubSchemaExport(repoRoot, "schema://hub.artifact-authority.trusted-catalog/TrustedCatalogPublicationCommandV1");
  const validateReceipt = hubSchemaExport(repoRoot, "schema://hub.artifact-authority.trusted-catalog/TrustedCatalogPublicationReceiptV1");
  const pointerShape = hubSchemaExport(repoRoot, "schema://hub.artifact-authority.trusted-catalog/TrustedCatalogCurrentPointerV1");
  assert(validateCommand(command), "publication command fixture must satisfy the scope-owned contract");
  for (const law of fixture.commandCases) {
    const candidate: Record<string, unknown> = { ...command, ...law.set };
    for (const key of law.remove) delete candidate[key];
    assertObservationExpectation(`command ${law.id}`, law.expectation as ObservationExpectation, Boolean(validateCommand(candidate)));
  }
  assert.deepEqual(JSON.parse(canonicalJson(command)), command);
  const transport = JSON.parse(readFileSync(join(root, "📡️transport.json"), "utf8"));
  assert.deepEqual(transport, {
    schema: "semio.hub.trusted-publication-transport/v1",
    command: ["trusted-catalog", "publish"],
    commandBytes: 4096,
    receiptBytes: 4096,
    inputDeadlineMs: 5000,
    publicationDeadlineMs: 30_000,
    outcomes: [
      { outcome: "durable", exit: "success", activate: true },
      { outcome: "replaced-unconfirmed", exit: "failure", activate: false },
      { outcome: "missing-or-invalid", exit: "failure", activate: false },
    ],
    rejectedArguments: [["trusted-catalog"], ["publish"], ["trusted-catalog", "publish", "--force"], ["trusted-catalog", "activate"]],
    processCases: [
      { mode: "durable", result: "durable" }, { mode: "unconfirmed", result: "unconfirmed" }, { mode: "unconfirmed-zero", result: "indeterminate" },
      { mode: "unconfirmed-two", result: "indeterminate" }, { mode: "overflow", result: "indeterminate" }, { mode: "signal", result: "indeterminate" },
      { mode: "empty", result: "indeterminate" }, { mode: "identity", result: "indeterminate" }, { mode: "durable-one", result: "indeterminate" },
      { mode: "timeout", result: "indeterminate" }, { mode: "cancel", result: "indeterminate" }, { mode: "durable-after-cancel", result: "durable" },
    ],
  });
  const pointerBytes = new TextEncoder().encode(JSON.stringify({ profileId: command.profileId, generationId: command.generationId, bundleSha256: command.bundleSha256, publicationRevision: "1" }) + "\n");
  const currentSha256 = Buffer.from(await webcrypto.subtle.digest("SHA-256", pointerBytes)).toString("hex");
  const receiptFixture = { schema: "semio.hub.trusted-catalog-publication-receipt/v1", requestId: command.requestId, profileId: command.profileId, generationId: command.generationId, bundleSha256: command.bundleSha256, publicationRevision: "1", currentSha256, outcome: "durable" };
  for (const row of transport.outcomes) {
    if (row.outcome === "missing-or-invalid") { assert.throws(() => trustedBootstrapPublicationReceipt(new Uint8Array(), command, "1")); continue; }
    const receipt = { ...receiptFixture, outcome: row.outcome };
    assert(validateReceipt(receipt), `${row.outcome} receipt must satisfy the scope-owned contract`);
    const result = trustedBootstrapPublicationReceipt(Buffer.from(JSON.stringify(receipt) + "\n"), command, "1");
    assert.equal(result.outcome === "durable", row.activate);
    assert.equal(result.currentSha256, currentSha256);
  }
  for (const law of fixture.receiptCases) {
    const candidate = { ...receiptFixture, ...law.set };
    assertObservationExpectation(`receipt ${law.id}`, law.expectation as ObservationExpectation, Boolean(validateReceipt(candidate)));
    const decode = (): unknown => trustedBootstrapPublicationReceipt(Buffer.from(JSON.stringify(candidate) + "\n"), command, "1");
    if (law.expectation.result === "accepted") decode();
    else assert.throws(decode, `receipt ${law.id} must be refused by the production decoder`);
  }
  const artifactRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
  assert(artifactRoot !== undefined && artifactRoot.includes("🗑️generated"));
  const evidence = mkdtempSync(join(artifactRoot, "publication-fence-"));
  const fixtureChild = `
    const fs = require("node:fs"), crypto = require("node:crypto"), path = require("node:path");
    const command = JSON.parse(fs.readFileSync(0, "utf8"));
    const mode = process.argv[1];
    fs.writeFileSync(path.join(process.env.OS_HUB_DATA, "child-ready.json"), JSON.stringify({ pid: process.pid, mode }));
    if (mode === "timeout" || mode === "cancel") { setInterval(() => {}, 1000); }
    else if (mode !== "empty") {
      const pointer = { profileId: command.profileId, generationId: command.generationId, bundleSha256: command.bundleSha256, publicationRevision: "1" };
      const outcome = ["unconfirmed", "unconfirmed-zero", "unconfirmed-two", "overflow", "signal"].includes(mode) ? "replaced-unconfirmed" : "durable";
      const receipt = { schema: "semio.hub.trusted-catalog-publication-receipt/v1", requestId: command.requestId, ...pointer, currentSha256: crypto.createHash("sha256").update(JSON.stringify(pointer) + "\\n").digest("hex"), outcome };
      if (mode === "identity") receipt.requestId = "ff".repeat(16);
      process.exitCode = mode === "unconfirmed-two" ? 2 : ["unconfirmed", "durable-one", "overflow", "signal"].includes(mode) ? 1 : 0;
      process.stdout.write(JSON.stringify(receipt) + "\\n", () => {
        if (mode === "overflow") process.stdout.write(" ".repeat(4097));
        if (mode === "signal") process.kill(process.pid, "SIGKILL");
      });
    }
  `;
  for (const row of transport.processCases) {
    const caseRoot = join(evidence, `child-${row.mode}`);
    mkdirSync(caseRoot);
    const started = Date.now(), input = Buffer.from(JSON.stringify(command) + "\n");
    const result = await runTrustedPublicationChild(process.execPath, ["-e", fixtureChild, row.mode], input, caseRoot, caseRoot, {
      cancelled: () => row.mode === "cancel" && existsSync(join(caseRoot, "child-ready.json")),
      remainingMs: () => Math.max(0, (row.mode === "timeout" ? 500 : 5000) - (Date.now() - started)),
    });
    let actual = "indeterminate";
    try { trustedPublicationChildReceipt(result, command, "1", caseRoot); actual = "durable"; }
    catch (error) { if (error instanceof TrustedBootstrapPublicationUnconfirmed) actual = "unconfirmed"; }
    assert.equal(actual, row.result, row.mode);
    assert(result.status !== null || result.signal !== null, `${row.mode}: child not reaped`);
    assert(statSync(join(caseRoot, "publication.stdout.json")).size <= 4096);
    assert(statSync(join(caseRoot, "publication.stderr.txt")).size <= 65536);
    if (row.mode === "cancel") { assert(existsSync(join(caseRoot, "child-ready.json"))); assert.equal(result.failed, "publication cancelled"); }
    if (row.mode === "timeout") assert.equal(result.failed, "publication timed out");
    if (row.mode === "overflow") assert.equal(result.failed, "publication stdout exceeded its receipt bound");
    result.bytes.fill(0); input.fill(0);
  }
  const ownerFixture = JSON.parse(readFileSync(join(root, "🔒️owner.json"), "utf8"));
  assert.deepEqual(ownerFixture, {
    schema: "semio.hub.trusted-publication-owner/v1",
    before: "previous-selection\n",
    after: "next-selection\n",
    nonce: "0123456789abcdef0123456789abcdef",
    lock: { first: "acquired", competing: "contended", afterDrop: "acquired" },
    replacement: { selected: "next-selection\n", foreignRoot: "foreign-selection\n" },
    process: { holder: "acquired", competing: "contended", afterCrash: "acquired", current: "unchanged" },
    cases: ["same-directory-replace", "cancel-before-replace", "duplicate-nonce-refused", "root-replacement-isolated", "lock-link-refused", "lock-directory-refused", "process-crash-releases-lock"],
  });
  const ownerOracle = join(evidence, "owner-oracle");
  mkdirSync(ownerOracle);
  writeFileSync(join(ownerOracle, "current.json"), ownerFixture.before);
  writeFileSync(join(ownerOracle, "next.json"), ownerFixture.after, { flag: "wx" });
  renameSync(join(ownerOracle, "next.json"), join(ownerOracle, "current.json"));
  assert.equal(readFileSync(join(ownerOracle, "current.json"), "utf8"), ownerFixture.replacement.selected);
  const cas = JSON.parse(readFileSync(join(root, "🔄️cas.json"), "utf8"));
  assert.deepEqual(cas, {
    schema: "semio.hub.trusted-publication-cas/v1",
    cases: [
      { id: "initial", currentRevision: null, nextRevision: "1", accepted: true },
      { id: "next", currentRevision: "1", nextRevision: "2", accepted: true },
      { id: "stale", currentRevision: "2", expectedRevision: "1", accepted: false },
      { id: "aba", currentRevision: "3", expectedRevision: "1", sameGeneration: true, accepted: false },
      { id: "maximum", currentRevision: "18446744073709551615", accepted: false },
      { id: "zero", currentRevision: "0", accepted: false },
      { id: "leading-zero", currentRevision: "01", accepted: false },
      { id: "overflow", currentRevision: "18446744073709551616", accepted: false },
    ],
    publicationOutcomes: ["durable", "replaced-unconfirmed"],
  });
  const pointerFor = (publicationRevision: string) => ({ profileId: fixture.profileId, generationId: fixture.generationId, bundleSha256: "42".repeat(32), publicationRevision });
  for (const row of cas.cases) {
    const casRoot = join(evidence, `cas-${row.id}`);
    mkdirSync(join(casRoot, "trusted-catalog"), { recursive: true });
    if (row.currentRevision !== null) writeFileSync(join(casRoot, "trusted-catalog/current.json"), JSON.stringify(pointerFor(row.currentRevision)) + "\n");
    let accepted = false;
    try {
      if (row.currentRevision !== null) assert(pointerShape(pointerFor(row.currentRevision)));
      const current = trustedBootstrapReadCurrentPointer(casRoot);
      if (row.expectedRevision !== undefined) {
        const bytes = Buffer.from(JSON.stringify(pointerFor(row.expectedRevision)) + "\n");
        assert.equal(current?.sha256, await webSha256Hex(bytes));
      }
      const next = trustedBootstrapPublicationRevision((BigInt(current?.pointer.publicationRevision ?? "0") + 1n).toString());
      if (row.nextRevision !== undefined) assert.equal(next, row.nextRevision);
      accepted = true;
    } catch {}
    assert.equal(accepted, row.accepted, row.id);
  }
  const stageFixture = JSON.parse(readFileSync(join(root, "../🧱️generation-stage/🔣️.json"), "utf8"));
  const component = Buffer.from("abc");
  const digest = async (bytes: Uint8Array) => await webSha256Hex(bytes);
  const actorFixture = JSON.parse(readFileSync(join(root, "../🌐️browser-actor/🔣️.json"), "utf8"));
  const { packages, descriptors, modules } = trustedBootstrapStageFixturePackages(stageFixture, actorFixture.closed, component);
  for (const record of packages) {
    assert.equal(record.component.sha256, await digest(component));
    assert.equal(record.descriptor.sha256, await digest(descriptors.get(record.pluginId)!));
    assert.equal(record.pluginModule.sha256, await digest(modules.get(record.pluginId)!.manifest));
  }
  const bundle = Buffer.from(JSON.stringify({ schemaVersion: 3, profiles: [{ id: fixture.profileId, generationId: fixture.generationId }], packages }) + "\n");
  for (const row of fixture.cases) {
    const dataRoot = join(evidence, row.change), trustedRoot = join(dataRoot, "trusted-catalog"), generationRoot = join(trustedRoot, "generations", fixture.generationId);
    mkdirSync(join(generationRoot, "packages/gis/browser"), { recursive: true });
    mkdirSync(join(generationRoot, "packages/stdio"));
    for (const plugin of ["gis", "stdio"]) {
      writeFileSync(join(generationRoot, "packages", plugin, "component.wasm"), component);
      writeFileSync(join(generationRoot, "packages", plugin, "descriptor.semio"), descriptors.get(plugin)!);
      trustedBootstrapWriteFixturePluginModule(generationRoot, modules.get(plugin)!);
    }
    const actorPath = join(generationRoot, "packages/gis/browser/closed-actor.mjs"), bundlePath = join(generationRoot, "trusted-catalog.json");
    writeFileSync(actorPath, component); writeFileSync(bundlePath, bundle);
    const receipt = { profileId: fixture.profileId, generationId: fixture.generationId, bundlePath, bundleSha256: await digest(bundle) };
    trustedBootstrapVerifyGeneration(generationRoot, bundle, new Map(packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)])), () => {});
    const pointerPath = join(trustedRoot, "current.json"), previous = Buffer.from(JSON.stringify({ profileId: fixture.profileId, generationId: "dd".repeat(32), bundleSha256: "ee".repeat(32), publicationRevision: "1" }) + "\n");
    writeFileSync(pointerPath, previous);
    const changes: Readonly<Record<string, string>> = { component: join(generationRoot, "packages/gis/component.wasm"), descriptor: join(generationRoot, "packages/stdio/descriptor.semio"), actor: actorPath, "plugin-module": join(generationRoot, "packages/stdio/plugin-module.json"), bundle: bundlePath };
    const changed = changes[row.change];
    if (changed) writeFileSync(changed, "substituted-after-candidate-proof");
    if (row.accepted) {
      trustedBootstrapVerifyPublication(dataRoot, receipt);
    } else {
      assert.throws(() => trustedBootstrapVerifyPublication(dataRoot, receipt), /generation|bundle|rotation/);
    }
    assert.deepEqual(readFileSync(pointerPath), previous);
  }
  console.log(`trusted publication final-byte fence: scope-exports=3 WebCrypto=1 Node-replace-oracle=1 cases=${fixture.cases.length} command-cases=${fixture.commandCases.length} receipt-cases=${fixture.receiptCases.length} revision-cases=${cas.cases.length} transport-outcomes=3 real-child-cases=${transport.processCases.length}; native-owner/CAS remain unqualified; evidence=${evidence}`);
}

/** ♾️ The repository's unlimited build budget (`SEMIO_BUILD_BUDGET_MS` unset, so [[BUILD_BUDGET_MS]] is `0`)
 * expressed inside the fresh-component process contract, whose own window is 1..86_400_000 ms and therefore
 * admits neither a zero nor an infinite deadline. */
const UNLIMITED_TRUSTED_BUILD_DEADLINE_MS = 86_400_000;

/** ⏳️ Owns interrupt and progress observation for a bounded catalog build, reading a zero deadline as the
 * repository-wide unlimited budget rather than as one that already expired. */
function trustedBootstrapBuildControl(deadlineMs: number): { control: FreshBuildControlV1; close(): void } {
  const deadline = deadlineMs > 0 ? Math.min(deadlineMs, UNLIMITED_TRUSTED_BUILD_DEADLINE_MS) : UNLIMITED_TRUSTED_BUILD_DEADLINE_MS;
  const diagnosticsRoot = process.env.SEMIO_TEST_ARTIFACT_DIR;
  let interrupted = false;
  const interrupt = (): void => {
    interrupted = true;
  };
  process.on("SIGINT", interrupt);
  process.on("SIGTERM", interrupt);
  const started = Date.now();
  return {
    control: Object.freeze({
      ...(diagnosticsRoot ? { diagnosticsRoot } : {}),
      cancelled: () => interrupted,
      remainingMs: () => Math.max(0, deadline - (Date.now() - started)),
      checkpoint(stage, completed, total) {
        console.log(`trusted-stdio-gis-bootstrap ${stage}: ${completed}/${total}`);
      },
    }),
    close() {
      process.off("SIGINT", interrupt);
      process.off("SIGTERM", interrupt);
    },
  };
}

