#!/usr/bin/env bun
/** 🧬️ Independent language-neutral mutation payload placement oracle. */
import Ajv from "ajv";
import { strict as assert } from "node:assert";
import picomatch from "picomatch";
import { mutationDomainOwnersProblems, mutationOwnerIdentity, loadCatalogTaxonomy } from "../../../../../../🦑️repo/🔨️modules/📚️library/🔍️discovery/🟦️.ts";

type LayoutCase = { readonly name: string; readonly accepted: boolean; readonly relativeSource?: string };

const fixture = await Bun.file(new URL("../../🧫️fixtures/🛂️mutation-source-authority/🔣️.json", import.meta.url)).json();
const document = await Bun.file(new URL("../../🧬️schema/🔣️.json", import.meta.url)).json();
const ajv = new Ajv({ strict: true, allErrors: true });
ajv.addSchema(document);
const validate = ajv.getSchema(`${document.$id}#/$defs/MutationSourceAuthorityV1`)!;
assert(validate(fixture), JSON.stringify(validate.errors));

const acceptsLayout = (source: string): boolean => {
  const segments = source.split("/");
  const collection = segments.indexOf("🧬️mutations");
  if (collection < 0 || segments.at(-1) !== "🦀️.rs") return false;
  const tail = segments.slice(collection + 1);
  return tail.length === 2 || tail.length === 3 && tail[1] === "🦠️mutation";
};

const layoutCases = (fixture.cases as LayoutCase[]).filter((item) => item.relativeSource !== undefined);
for (const item of layoutCases) assert.equal(acceptsLayout(item.relativeSource!), item.accepted, item.name);
const hostile = [
  { ...fixture, extra: true },
  { ...fixture, cases: [...fixture.cases, { name: "invalid", accepted: true, relativeSource: "" }] },
];
for (const item of hostile) assert(!validate(item));
assert(!acceptsLayout("domain/🧬️mutations/🆕️insert-page/unknown/🦀️.rs"));
assert(!acceptsLayout("domain/🧬️mutations/🆕️insert-page/🦠️mutation/nested/🦀️.rs"));

const domainFixture = await Bun.file(new URL("../../../../../../../🔨️modules/📡️replication/🎮️mutation/🧫️fixtures/🛂️mutation-source-authority/🧭️domains.json", import.meta.url)).json();
const taxonomy = { ...loadCatalogTaxonomy(), mutationDomainOwners: { [domainFixture.mutationRoot]: domainFixture.domains } };
assert.deepEqual(mutationDomainOwnersProblems(taxonomy.mutationDomainOwners), []);
const explicitOwners = Object.entries(domainFixture.domains).flatMap(([domain, operations]) => Object.entries(operations as Record<string, string>).map(([operation, identity]) => ({ owner: `${domain}/${operation}`, identity })));
for (const vector of domainFixture.cases) {
  const sourceAllowed = vector.source === "🦀️.rs" || vector.source === "🦠️mutation/🦀️.rs";
  const independent = !vector.fault && sourceAllowed && explicitOwners.some((item) => picomatch(item.owner, { literalBrackets: true })(vector.owner) && item.identity === vector.semanticKind);
  const subject = !vector.fault && sourceAllowed && mutationOwnerIdentity(domainFixture.mutationRoot, vector.owner, taxonomy) === vector.semanticKind;
  assert.equal(independent, vector.accepted, vector.name);
  assert.equal(subject, independent, vector.name);
}

/** 🧹️ Strict cross-language nested-value retirement laws; source oracle only. */
import Ajv from "ajv";
import { strict as assert } from "node:assert";
import stableStringify from "fast-json-stable-stringify";

//#region 🧬️RetirementContracts
const contracts = await Bun.file(new URL("../../🧬️schema/🔣️.json", import.meta.url)).json();
const ajv = new Ajv({ strict: true, allErrors: true }).addSchema(contracts);
/** 🧬️Resolves one named retirement contract export from the module schema. */
const contract = (exportId: string) => ajv.getSchema(`${contracts.$id}#/$defs/${exportId}`)!;
//#endregion 🧬️RetirementContracts

//#region 🔣️DomainFixture
const fixture = await Bun.file(new URL("../../🧫️fixtures/🔣️value-retirement.json", import.meta.url)).json();
const validate = contract("ValueRetirementV1");
assert(validate(fixture), JSON.stringify(validate.errors));
const bytes = (value: any): number => typeof value === "string" ? Buffer.byteLength(value) : value && typeof value === "object" ? Object.entries(value).reduce((sum, [key, child]) => sum + Buffer.byteLength(key) + bytes(child), 0) : 0;
for (const row of fixture.cases) {
  const value = JSON.parse(row.json.replaceAll("$text", row.expandedText.text.repeat(row.expandedText.repetitions)));
  assert.equal(bytes(value), row.expectedBytes);
  assert.deepEqual(JSON.parse(stableStringify(value)), value);
  for (const grant of fixture.grants) {
    let remaining = row.expectedBytes; let released = 0;
    while (remaining) { const step = Math.min(grant, remaining); remaining -= step; released += step; }
    assert.equal(released, row.expectedBytes);
  }
}
for (const mutate of [(value: any) => { value.extra = true; }, (value: any) => { value.grants = [16384]; }, (value: any) => { value.ownership.finalDrop = "recursive-drop"; }, (value: any) => { value.cases[0].expandedText.repetitions = -1; }]) {
  const mutant = structuredClone(fixture); mutate(mutant); assert(!validate(mutant));
}
//#endregion 🔣️DomainFixture

//#region 🧠️CacheFixture
const cacheFixture = await Bun.file(new URL("../../🧫️fixtures/🗃️cache-retirement/🔣️.json", import.meta.url)).json();
const validateCache = contract("CacheRetirementV1");
assert(validateCache(cacheFixture), JSON.stringify(validateCache.errors));
const cache = new Map<number, Record<string, string>>(); const pending: Record<string, string>[] = [];
let finalBytes = 0;
for (const operation of cacheFixture.operations) {
  if (operation.op === "seed") {
    const old = cache.get(cacheFixture.key); if (old) pending.push(old);
    cache.set(cacheFixture.key, { [operation.field]: operation.text.repeat(operation.repeat) });
  } else if (operation.op === "release-shared") {
    assert.equal(cache.size, cacheFixture.expected.liveEntriesBeforeFinal);
    assert.equal(finalBytes, cacheFixture.expected.sharedReleasedBytes);
    const current = cache.get(cacheFixture.key)!;
    const expected = cacheFixture.expected.finalJson.replace("$text", cacheFixture.operations[1].text.repeat(cacheFixture.operations[1].repeat));
    assert.equal(stableStringify(current), expected);
  } else {
    finalBytes = [...pending, ...cache.values()].reduce((sum, value) => sum + bytes(value), 0);
    pending.length = 0; cache.clear();
  }
}
assert.equal(finalBytes, cacheFixture.expected.finalReleasedBytes); assert.equal(cache.size + pending.length, cacheFixture.expected.terminalOwners);
for (const mutant of [{ ...cacheFixture, extra: true }, { ...cacheFixture, expected: { ...cacheFixture.expected, sharedReleasedBytes: 1 } }, { ...cacheFixture, operations: [{ op: "erase" }, ...cacheFixture.operations.slice(1)] }]) assert(!validateCache(mutant));
//#endregion 🧠️CacheFixture

//#region 📸️EvaluationOwnership
const evaluation = await Bun.file(new URL("../../🧫️fixtures/🧮️evaluation-owners/🔣️.json", import.meta.url)).json();
const validateEvaluation = contract("EvaluationOwnersV1");
assert(validateEvaluation(evaluation), JSON.stringify(validateEvaluation.errors));
const node = evaluation.node.text.repeat(evaluation.node.repeat); const payload = evaluation.payload.text.repeat(evaluation.payload.repeat);
assert.equal(Buffer.byteLength(node) + 2 * Buffer.byteLength(payload) + Buffer.byteLength("seednodelabel"), evaluation.expectedBytes);
assert.equal(stableStringify({ node: { label: payload } }), JSON.stringify({ node: { label: payload } }));
for (const mutant of [{ ...evaluation, extra: true }, { ...evaluation, expectedBytes: 0 }]) assert(!validateEvaluation(mutant));
//#endregion 📸️EvaluationOwnership

