    const matches = proofs.filter((proof) => proof.ownerFile === row.file && proof.toolId === row.id);
    if (matches.length !== 1) failures.push(`Migrated declaration has ${matches.length} exact bounded reducer proofs ${row.file}\0${row.id}`);
  }
  return failures;
}

