    if (segments[0] === "resolved-host-context") {
      const { testResolvedHostContext } = await import("./🧰️framework/🔨️modules/🛂️manifest/🪟️view-context/🧪️tests/🪟️resolved-host-context/🟦️.ts");
      testResolvedHostContext();
