test("Semio object shared exact geometry parser, child identity, optional presence and controls",async()=>{for(const hex of f.float64Bits){const s=structuredClone(input),word={bits:BigInt("0x"+hex)};s.transform.translation={x:word,y:word,z:word};s.transform.rotation={x:word,y:word,z:word,w:word};s.transform.scale={x:word,y:word,z:word};expect(parseSemioObjectSnapshot(s)).toEqual(s);const db=Database.deserialize(await exportSqliteDatabase(await semioObjectSnapshotToSqliteDatabase(s)));try{expect(await semioObjectSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}const d=await semioObjectSnapshotToSqliteDatabase(input);for(const mutate of [(x:any)=>x.tables[1].rows[1].values[4]="value",(x:any)=>x.tables[1].rows[1].values[2]="foreign.artifact",(x:any)=>x.tables[3].rows[0].values[3]=x.tables[2].rows[0].values[3],(x:any)=>x.tables[0].rows[0].values[1]="other"]){const x=structuredClone(d);mutate(x);await expect(semioObjectSnapshotFromSqliteDatabase(x)).rejects.toThrow();}await expect(semioObjectSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(semioObjectSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(semioObjectSnapshotToSqliteDatabase(input,{signal:c.signal})).rejects.toThrow();const empty={schema:"stdio.semio.object"as const,transform:input.transform};expect(await semioObjectSnapshotFromSqliteDatabase(await semioObjectSnapshotToSqliteDatabase(empty))).toEqual(empty);});

test("Semio object distinct local child aliases preserve independent target identities",async()=>{for(const alias of f.distinctAliases){const s=structuredClone(input);s.mesh={childId:alias.childId,target:{artifactId:alias.artifactId,dialect:{artifactKind:"s.stdio.semio",standard:"v1",subset:"mesh"}}};expect(parseSemioObjectSnapshot(s)).toEqual(s);const db=Database.deserialize(await exportSqliteDatabase(await semioObjectSnapshotToSqliteDatabase(s)));try{expect(db.query("SELECT child_id,artifact_id FROM semio_object_mesh_child JOIN semio_object_reference ON target_reference_id=semio_object_reference.id").get()).toEqual({child_id:alias.childId,artifact_id:alias.artifactId});expect(await semioObjectSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(s);}finally{db.close();}}});

import completeSemanticContract from "../🧫️fixtures/🎛️semantic.json";
import completeSemanticSchema from "../🧫️fixtures/🧬️semantic.json";
import Ajv2020Complete from "ajv/dist/2020";
import{independentSqliteExtent as completeIndependentExtent} from "../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧪️tests/🔮️semantic-extent/🟦️.ts";
test("Semio Object matched Native exact words and optional-child emptiness preserve complete cells",async()=>{
 expect(new Ajv2020Complete({strict:true}).compile(completeSemanticSchema)(completeSemanticContract)).toBe(true);
 for(const item of completeSemanticContract.cases){const source=structuredClone(input);if(item.empty){delete source.brep;delete source.mesh;delete source.properties;}if(item.word!==null)source.transform.translation.x={bits:BigInt("0x"+item.word)};const database=await semioObjectSnapshotToSqliteDatabase(source),bytes=await exportSqliteDatabase(database);expect(completeIndependentExtent(bytes)).toEqual({rows:item.rows,valueBytes:item.valueBytes,schemaBytes:completeSemanticContract.schemaBytes,tableWidths:completeSemanticContract.tableWidths});const limits={maxRows:item.rows,maxValueBytes:item.valueBytes,maxSchemaBytes:completeSemanticContract.schemaBytes,maxTables:5,maxColumns:32};expect(await semioObjectSnapshotToSqliteDatabase(source,limits)).toEqual(database);expect(await semioObjectSnapshotFromSqliteDatabase(await importSqliteDatabase(bytes),limits)).toEqual(source);
 for(const short of[{...limits,maxRows:item.rows-1},{...limits,maxValueBytes:item.valueBytes-1},{...limits,maxSchemaBytes:limits.maxSchemaBytes-1},{...limits,maxTables:4},{...limits,maxColumns:31}]){await expect(semioObjectSnapshotToSqliteDatabase(source,short)).rejects.toThrow();await expect(semioObjectSnapshotFromSqliteDatabase(database,short)).rejects.toThrow();}
 }console.log("[DEBUG] Semio Object independently measured18 matched exact-word and optional-empty cell cases under all5 copied limits");
});

